import { Link } from 'react-router-dom'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { quickActionsFor } from '@/app/nav'
import { useOwned, byCreatedDesc } from '@/db/hooks'
import type { Bill, CalendarEvent, Need, Task, Topic } from '@/types/domain'
import { useI18n } from '@/i18n'
import { formatRupiah, greetingKey, mentalLoadLabel, whenLabel } from '@/i18n/format'
import MainFeatures from './MainFeatures'

/**
 * "Hari ini" — the app-first landing surface (blueprint 04 §6).
 * No marketing, no hero copy: what needs attention, then how to add to it.
 */
export default function Today() {
  const { t, locale } = useI18n()
  const { profile } = useSession()
  const me = profile?.id
  const today = format(new Date(), 'yyyy-MM-dd')

  const events = useOwned<CalendarEvent>('events', me)
  const tasks = useOwned<Task>('tasks', me)
  const bills = useOwned<Bill>('bills', me)
  const needs = useOwned<Need>('needs', me, byCreatedDesc)
  const topics = useOwned<Topic>('topics', me, byCreatedDesc)

  if (!profile) return null

  const upcoming = (events ?? []).filter((e) => e.date >= today).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 4)
  const openTasks = (tasks ?? []).filter((t) => t.status !== 'done').slice(0, 4)
  const dueBills = (bills ?? []).filter((b) => b.status === 'unpaid').sort((a, b) => a.dueDate.localeCompare(b.dueDate)).slice(0, 3)
  const openNeeds = (needs ?? []).filter((n) => !n.resolvedAt).slice(0, 3)
  const openTopics = (topics ?? []).filter((t) => t.status === 'open' || t.status === 'scheduled').slice(0, 3)

  const quiet =
    upcoming.length === 0 && openTasks.length === 0 && dueBills.length === 0 && openNeeds.length === 0

  return (
    <div className="stack">
      <section className="hero stack stack--tight">
        <p className="card__hint" style={{ color: 'var(--ink)' }}>
          {t('today.greeting', { part: t(greetingKey()), name: profile.displayName })}
        </p>
        <h1>{quiet ? t('today.quiet') : t('today.busy')}</h1>
        <p className="card__hint">
          {quiet
            ? t('today.quietHint')
            : t('today.busyHint', {
                events: upcoming.length,
                tasks: openTasks.length,
                bills: dueBills.length,
              })}
        </p>
      </section>

      {/* The four the app is actually for, before anything else on the page. */}
      <MainFeatures me={profile.id} />

      <nav aria-label={t('today.quickAdd')}>
        <div className="row" style={{ gap: 'var(--space-2)' }}>
          {quickActionsFor(profile.stage).map((a) => (
            <Link key={a.id} to={a.to} className="btn btn--soft btn--sm">
              <Icon name={a.icon} size={16} />
              {t(a.label)}
            </Link>
          ))}
        </div>
      </nav>

      <Card
        title={t('today.upcoming')}
        icon="calendar"
        action={
          <Link to="/kalender" className="btn btn--ghost btn--sm">
            {t('nav.calendar')}
          </Link>
        }
      >
        {upcoming.length === 0 ? (
          <EmptyState
            sticker="empty-calendar"
            title={t('today.noUpcoming')}
            hint={t('today.noUpcomingHint')}
            action={
              <Link to="/kalender?baru=1" className="btn btn--sm">
                {t('today.addEvent')}
              </Link>
            }
          />
        ) : (
          <ul className="list">
            {upcoming.map((e) => (
              <li key={e.id} className="list__item">
                <Icon name={e.type === 'bill' ? 'money' : e.type === 'date' ? 'date' : 'calendar'} size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>
                    {e.visibility === 'private' && e.maskedTitle ? e.title : e.title}
                  </strong>
                  <span className="card__hint">
                    {whenLabel(e.date, t, locale)}
                    {e.time ? ` · ${e.time}` : ''}
                  </span>
                </span>
                <VisibilityBadge visibility={e.visibility} />
              </li>
            ))}
          </ul>
        )}
      </Card>

      {profile.stage !== 'single' && (
        <Card
          title={t('today.unsaid')}
          icon="heart"
          action={
            <Link to="/hubungan" className="btn btn--ghost btn--sm">
              {t('common.open')}
            </Link>
          }
        >
          {openNeeds.length === 0 && openTopics.length === 0 ? (
            <EmptyState
              sticker="empty-wish"
              title={t('today.noUnsaid')}
              hint={t('today.noUnsaidHint')}
            />
          ) : (
            <ul className="list">
              {openNeeds.map((n) => (
                <li key={n.id} className="list__item">
                  <Icon name="heart" size={18} />
                  <span className="grow">{n.text}</span>
                  <VisibilityBadge visibility={n.visibility} />
                </li>
              ))}
              {openTopics.map((topic) => (
                <li key={topic.id} className="list__item">
                  <Icon name="checkin" size={18} />
                  <span className="grow">{topic.title}</span>
                  <span className="chip">
                    {topic.status === 'scheduled' ? t('today.scheduled') : t('today.notYet')}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      )}

      {profile.stage !== 'single' && (
        <Card
          title={t('today.running')}
          icon="tasks"
          action={
            <Link to="/kehidupan" className="btn btn--ghost btn--sm">
              {t('common.open')}
            </Link>
          }
        >
          {openTasks.length === 0 && dueBills.length === 0 ? (
            <EmptyState sticker="empty-list" title={t('today.noRunning')} hint={t('today.noRunningHint')} />
          ) : (
            <ul className="list">
              {openTasks.map((task) => (
                <li key={task.id} className="list__item">
                  <Icon name="tasks" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{task.title}</strong>
                    <span className="card__hint">
                      {task.dueDate ? whenLabel(task.dueDate, t, locale) : t('common.noDeadline')} ·{' '}
                      {mentalLoadLabel(task.mentalLoadType, t)}
                    </span>
                  </span>
                </li>
              ))}
              {dueBills.map((b) => (
                <li key={b.id} className="list__item">
                  <Icon name="money" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{b.title}</strong>
                    <span className="card__hint">
                      {formatRupiah(b.amount, locale)} · {t('fin.due', { when: whenLabel(b.dueDate, t, locale) })}
                    </span>
                  </span>
                </li>
              ))}
            </ul>
          )}
        </Card>
      )}

      <Card title={t('today.heavy')} icon="referral" hint={t('today.heavyHint')}>
        <Link to="/bantuan" className="btn btn--ghost btn--block">
          <Icon name="referral" size={18} />
          {t('today.findHelp')}
        </Link>
      </Card>
    </div>
  )
}
