import Dexie, { type EntityTable } from 'dexie'
import {
  DEFAULT_VISIBILITY,
  SCHEMA_VERSION,
  canRead,
  type Appreciation,
  type AuditEvent,
  type Bill,
  type CalendarEvent,
  type CheckIn,
  type CycleDay,
  type CycleLog,
  type DataClass,
  type EmergencyContact,
  type Envelope,
  type FamilyRecord,
  type GroceryItem,
  type HouseholdDocument,
  type MoneyMeeting,
  type Memory,
  type Need,
  type Pair,
  type Profile,
  type RepairRequest,
  type SharedGoal,
  type Task,
  type Topic,
  type WeddingRecord,
  type WishRecord,
} from '@/types/domain'

/**
 * Store layout follows blueprint 06 §7. Records keep their envelope inline so a
 * single `get` answers "may this viewer read it?" without a second lookup.
 */
export class TemuDuaDB extends Dexie {
  profiles!: EntityTable<Profile, 'id'>
  pairs!: EntityTable<Pair, 'id'>
  checkins!: EntityTable<CheckIn, 'id'>
  needs!: EntityTable<Need, 'id'>
  appreciations!: EntityTable<Appreciation, 'id'>
  topics!: EntityTable<Topic, 'id'>
  repairs!: EntityTable<RepairRequest, 'id'>
  events!: EntityTable<CalendarEvent, 'id'>
  tasks!: EntityTable<Task, 'id'>
  bills!: EntityTable<Bill, 'id'>
  memories!: EntityTable<Memory, 'id'>
  cycles!: EntityTable<CycleLog, 'id'>
  cycleDays!: EntityTable<CycleDay, 'id'>
  wedding!: EntityTable<WeddingRecord, 'id'>
  family!: EntityTable<FamilyRecord, 'id'>
  groceries!: EntityTable<GroceryItem, 'id'>
  documents!: EntityTable<HouseholdDocument, 'id'>
  contacts!: EntityTable<EmergencyContact, 'id'>
  goals!: EntityTable<SharedGoal, 'id'>
  meetings!: EntityTable<MoneyMeeting, 'id'>
  wishes!: EntityTable<WishRecord, 'id'>
  // v4 feature stores whose bodies are discriminated unions built from
  // feature-local vocabularies (`choreMath.DomainKey`, `finance/money`). The
  // envelope is the part `db.ts` has to know about; the body type stays with
  // the feature and arrives via `useOwned<T>()` / `readable<T>()` at the call
  // site. Dragging those unions in here would make domain.ts depend on feature
  // logic, which is the wrong direction.
  domains!: EntityTable<Envelope, 'id'>
  accounts!: EntityTable<Envelope, 'id'>
  ledger!: EntityTable<Envelope, 'id'>
  splits!: EntityTable<Envelope, 'id'>
  contributionRules!: EntityTable<Envelope, 'id'>
  proposals!: EntityTable<Envelope, 'id'>
  audit!: EntityTable<AuditEvent, 'seq'>
  settings!: EntityTable<{ key: string; value: unknown }, 'key'>

  constructor(name = 'temudua') {
    super(name)
    // v1 — initial schema. Later versions append `.version(n).stores(...).upgrade()`;
    // never mutate this block, or existing installs migrate to the wrong shape.
    this.version(1).stores({
      profiles: 'id, stage',
      pairs: 'id, status',
      checkins: 'id, ownerProfileId, date, deletedAt',
      needs: 'id, ownerProfileId, visibility, deletedAt',
      appreciations: 'id, ownerProfileId, createdAt, deletedAt',
      topics: 'id, ownerProfileId, status, deletedAt',
      repairs: 'id, ownerProfileId, status, deletedAt',
      events: 'id, ownerProfileId, date, type, deletedAt',
      tasks: 'id, ownerProfileId, accountableProfileId, status, dueDate, deletedAt',
      bills: 'id, ownerProfileId, dueDate, status, space, deletedAt',
      memories: 'id, ownerProfileId, date, deletedAt',
      cycles: 'id, ownerProfileId, startDate, deletedAt',
      audit: '++seq, timestamp, objectId',
      settings: 'key',
    })

    // v2 — wedding (Phase 9) and family lifecycle (Phase 10). Two stores rather
    // than ten: `kind` discriminates, and every row keeps the same envelope, so
    // backup, audit, visibility, and unpair all work on them unchanged.
    this.version(2).stores({
      wedding: 'id, ownerProfileId, kind, status, deletedAt',
      family: 'id, ownerProfileId, kind, childId, date, deletedAt',
    })

    // v3 — the household and finance stores the first pass left out
    // (HOME-03/04/05/06, FIN-03). Separate stores, not another union: their
    // shapes and their indexes have nothing in common.
    this.version(3).stores({
      groceries: 'id, ownerProfileId, bought, deletedAt',
      documents: 'id, ownerProfileId, docKind, expiresAt, deletedAt',
      contacts: 'id, ownerProfileId, deletedAt',
      goals: 'id, ownerProfileId, achievedAt, deletedAt',
      meetings: 'id, ownerProfileId, date, deletedAt',
    })

    // v4 — the stores the second wave of features needed. No `.upgrade()`: every
    // one of them is new, so there is no existing row to migrate.
    //
    // `wishes` is one store, not two: a reservation is a separate *record* (so
    // `canRead()` hides it from the wish's owner) but it shares the envelope and
    // the index shape, so `kind` discriminates exactly like `wedding`/`family`.
    //
    // The five money stores stay separate because their indexes have nothing in
    // common, and because a ledger row and a proposal are read on different
    // screens at different rates.
    this.version(4).stores({
      wishes: 'id, ownerProfileId, kind, scope, wishId, fulfilledAt, deletedAt',
      domains: 'id, ownerProfileId, kind, deletedAt',
      accounts: 'id, ownerProfileId, space, deletedAt',
      ledger: 'id, ownerProfileId, accountId, date, deletedAt',
      splits: 'id, ownerProfileId, date, deletedAt',
      contributionRules: 'id, ownerProfileId, effectiveFrom, deletedAt',
      proposals: 'id, ownerProfileId, status, deletedAt',
    })

    // v5 — day-by-day cycle tracking. A new store rather than a field on
    // `cycles`: that record is about a period, this one is about a day, and a
    // symptom can be logged on a day with no bleeding at all. No `.upgrade()`
    // — nothing existing changes shape.
    //
    // `date` is indexed and unique per owner in practice (the writer looks the
    // day up before inserting), which is what keeps re-logging a day from
    // stacking duplicate rows.
    this.version(5).stores({
      cycleDays: 'id, ownerProfileId, date, deletedAt',
    })
  }
}

export const db = new TemuDuaDB()

/** Stores that hold envelope-wrapped records — the ones backup and unpair walk. */
export const OWNED_STORES = [
  'checkins',
  'needs',
  'appreciations',
  'topics',
  'repairs',
  'events',
  'tasks',
  'bills',
  'memories',
  'cycles',
  'cycleDays',
  'wedding',
  'family',
  'groceries',
  'documents',
  'contacts',
  'goals',
  'meetings',
  'wishes',
  'domains',
  'accounts',
  'ledger',
  'splits',
  'contributionRules',
  'proposals',
] as const
export type OwnedStore = (typeof OWNED_STORES)[number]

export function newId(): string {
  return crypto.randomUUID()
}

/** Builds an envelope with the class default. Callers may override visibility explicitly. */
export function newEnvelope(
  ownerProfileId: string,
  dataClass: DataClass,
  overrides: Partial<Envelope> = {},
): Envelope {
  const now = new Date().toISOString()
  return {
    id: newId(),
    schemaVersion: SCHEMA_VERSION,
    ownerProfileId,
    coOwnerProfileIds: [],
    dataClass,
    visibility: DEFAULT_VISIBILITY[dataClass],
    approvalStatus: 'not_required',
    sharedWithProfileIds: [],
    createdAt: now,
    updatedAt: now,
    version: 1,
    ...overrides,
  }
}

export async function logAudit(
  e: Omit<AuditEvent, 'seq' | 'timestamp'>,
): Promise<void> {
  await db.audit.add({ ...e, timestamp: new Date().toISOString() })
}

/**
 * Reads a store filtered to what `viewerProfileId` is actually allowed to see.
 * Feature code must use this rather than `db.<store>.toArray()` — the gate is
 * only worth anything if there is no path around it.
 */
export async function readable<T extends Envelope>(
  store: OwnedStore,
  viewerProfileId: string,
): Promise<T[]> {
  const rows = (await db.table(store).toArray()) as T[]
  return rows.filter((r) => canRead(r, viewerProfileId))
}

/** Changes visibility. Rejects non-owners rather than silently no-opping. */
export async function setVisibility(
  store: OwnedStore,
  objectId: string,
  actorProfileId: string,
  visibility: Envelope['visibility'],
  sharedWithProfileIds: string[] = [],
): Promise<void> {
  const row = (await db.table(store).get(objectId)) as Envelope | undefined
  if (!row) throw new Error(`Tidak ada data ${store}/${objectId}`)
  if (row.ownerProfileId !== actorProfileId) {
    throw new Error('Hanya pemilik data yang bisa mengubah siapa yang boleh lihat.')
  }
  const revoking = visibility === 'private' && row.visibility !== 'private'
  await db.table(store).update(objectId, {
    visibility,
    sharedWithProfileIds,
    updatedAt: new Date().toISOString(),
    version: row.version + 1,
    ...(revoking ? { revokedAt: new Date().toISOString() } : { revokedAt: undefined }),
  })
  await logAudit({
    actorProfileId,
    action: revoking ? 'revoke' : 'share',
    objectStore: store,
    objectId,
    summary: `visibility → ${visibility}`,
  })
}

/**
 * Partial update for the discriminated-union stores (`wedding`, `family`).
 * Dexie's `UpdateSpec` cannot express "some fields of one variant", so the cast
 * lives here once rather than at every call site.
 */
export async function patch(
  store: OwnedStore,
  id: string,
  changes: Record<string, unknown>,
): Promise<void> {
  await db.table(store).update(id, { ...changes, updatedAt: new Date().toISOString() } as never)
}

/** Soft delete. Permanent erase lives in the uncoupling/settings flow only. */
export async function softDelete(
  store: OwnedStore,
  objectId: string,
  actorProfileId: string,
): Promise<void> {
  await db.table(store).update(objectId, { deletedAt: new Date().toISOString() })
  await logAudit({
    actorProfileId,
    action: 'delete',
    objectStore: store,
    objectId,
    summary: 'soft delete',
  })
}
