import './decor.css'

/**
 * Decorative assets — drawn here, not imported, and never emoji.
 *
 * These exist because empty screens are where an app looks unfinished, and a
 * grey "Belum ada data" line is the most joyless thing a product can show
 * someone. Every sticker is a small scene with its own idle motion.
 *
 * Rules, same as the icon set:
 *   - one flat vocabulary: rounded strokes, generous radii, no gradients on
 *     linework, colour from tokens only.
 *   - `aria-hidden` by default. A decoration must never be the only way to
 *     learn something; the text next to it carries the meaning.
 *   - motion is transform/opacity, idles are slow (4s+) and low amplitude so a
 *     screen with two stickers on it does not twitch.
 */

export type StickerName =
  | 'empty-list' // nothing here yet — a basket with one leaf in it
  | 'empty-money' // no entries — a jar with two coins resting
  | 'empty-calendar' // no plans — a page with a sleeping moon
  | 'empty-wish' // no wishes — a tag on a string
  | 'celebrate' // something completed — a burst with two ribbons
  | 'privacy' // this is yours alone — a lock inside a soft shell
  | 'gentle' // rest / pause / no pressure — a cup with steam
  | 'together' // both partners — two arcs crossing, the app's core mark

export interface StickerProps {
  name: StickerName
  size?: number
  className?: string
  /** Give a label only when the sticker is the sole carrier of meaning. */
  label?: string
  /** Idle animation. On by default — these are display pieces, not list icons. */
  idle?: boolean
}

/** Motion class per sticker; like the icon set, each moves as its subject would. */
const IDLE: Record<StickerName, string> = {
  'empty-list': 'dc--sway', // the leaf sways, the basket does not
  'empty-money': 'dc--settle', // coins settle, one a beat later
  'empty-calendar': 'dc--doze', // the moon breathes slowly, asleep
  'empty-wish': 'dc--dangle', // the tag turns on its string
  celebrate: 'dc--burst', // ribbons drift outward and ease back
  privacy: 'dc--breathe', // the shell breathes around a still lock
  gentle: 'dc--steam', // steam rises and fades
  together: 'dc--cross', // the two arcs lean into each other
}

