export const STICKER_NAMES = Object.keys(ART) as StickerName[]
export const STICKER_IDLE: Readonly<Record<StickerName, string>> = IDLE

export function Sticker({ name, size = 96, className, label, idle = true }: StickerProps) {
  return (
    <svg
      className={['dc', idle ? IDLE[name] : '', className].filter(Boolean).join(' ')}
      width={size}
      height={size}
      viewBox="0 0 90 90"
      fill="none"
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      {ART[name]}
    </svg>
  )
}

/**
 * A soft organic blob for section backgrounds. `seed` picks one of four
 * silhouettes so two blobs on one screen are not obviously the same shape.
 */
export function Blob({
  seed = 0,
  className,
  style,
  tone = 'teal',
}: {
  seed?: number
  className?: string
  /** Position and size it at the call site — a blob is always placed by hand. */
  style?: React.CSSProperties
  tone?: 'teal' | 'primary' | 'lavender' | 'yellow'
}) {
  const paths = [
    'M43 3c14 0 30 8 34 22s-6 30-18 39-28 12-38 4S3 43 8 29 29 3 43 3Z',
    'M50 2c16 3 29 16 30 31s-11 28-25 34S22 74 12 62 2 32 12 20 34-1 50 2Z',
    'M40 4c17-2 33 7 38 21s-2 31-14 41-29 10-39 0S1 39 8 25 23 6 40 4Z',
    'M46 5c15 1 28 12 31 26s-5 30-17 39-29 9-38-2S2 39 10 25 31 4 46 5Z',
  ]
  return (
    <svg
      className={['dc-blob', `dc-blob--${tone}`, className].filter(Boolean).join(' ')}
      style={style}
      viewBox="0 0 90 90"
      aria-hidden="true"
      focusable="false"
    >
      <path d={paths[seed % paths.length]} />
    </svg>
  )
}
