import { useLiveQuery } from 'dexie-react-hooks'
import { readable, type OwnedStore } from './db'
import type { Envelope } from '@/types/domain'

/**
 * Live-reading a store through the visibility gate. Feature components use this
 * instead of touching Dexie tables, so there is exactly one read path to audit.
 */
export function useOwned<T extends Envelope>(
  store: OwnedStore,
  viewerProfileId: string | undefined,
  sort?: (a: T, b: T) => number,
): T[] | undefined {
  return useLiveQuery(async () => {
    if (!viewerProfileId) return []
    const rows = await readable<T>(store, viewerProfileId)
    return sort ? rows.sort(sort) : rows
  }, [store, viewerProfileId])
}

export const byCreatedDesc = (a: Envelope, b: Envelope) => b.createdAt.localeCompare(a.createdAt)
export const byDateAsc = (a: { date: string }, b: { date: string }) => a.date.localeCompare(b.date)
