import { format, isToday, isTomorrow, parseISO } from 'date-fns'
import { id as idLocale, enGB } from 'date-fns/locale'
import type { Locale, TFunction } from './index'
import type { MentalLoadType, Visibility } from '@/types/domain'

/**
 * Locale-aware formatting helpers.
 *
 * These live here rather than inside components so a date or a currency is
 * formatted the same way everywhere, and so no feature file has to know which
 * date-fns locale object corresponds to which app locale.
 */

export function dateLocale(locale: Locale) {
  return locale === 'en' ? enGB : idLocale
}

export function fmtDate(iso: string, pattern: string, locale: Locale): string {
  return format(parseISO(iso), pattern, { locale: dateLocale(locale) })
}

/** "Hari ini" / "Besok" / "Sen, 3 Agu" — the short label used in every list. */
export function whenLabel(iso: string, t: TFunction, locale: Locale): string {
  const d = parseISO(iso)
  if (isToday(d)) return t('common.today')
  if (isTomorrow(d)) return t('common.tomorrow')
  return format(d, 'EEE, d MMM', { locale: dateLocale(locale) })
}

/**
 * Rupiah, always. The app is Indonesian and the money is Rupiah regardless of
 * interface language — only the grouping separators follow the locale.
 */
export function formatRupiah(n: number, locale: Locale = 'id'): string {
  return new Intl.NumberFormat(locale === 'en' ? 'en-GB' : 'id-ID', {
    style: 'currency',
    currency: 'IDR',
    maximumFractionDigits: 0,
  }).format(n)
}

export function mentalLoadLabel(kind: MentalLoadType, t: TFunction): string {
  return t(`load.${kind}` as const)
}

export function visibilityLabel(v: Visibility, t: TFunction): string {
  return t(`vis.${v}` as const)
}

export function greetingKey(hours = new Date().getHours()) {
  if (hours < 11) return 'today.morning' as const
  if (hours < 15) return 'today.noon' as const
  if (hours < 19) return 'today.afternoon' as const
  return 'today.evening' as const
}
