import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import { db, logAudit, newId } from '@/db/db'
import type { PairingMode, Profile, Stage } from '@/types/domain'

/**
 * Session = who is using the device right now. On a shared phone the couple
 * switches profile here; every read gate downstream keys off `profile.id`.
 */

const ACTIVE_PROFILE_KEY = 'temudua.activeProfile'
const ONBOARDED_KEY = 'temudua.onboarded'

interface SessionValue {
  loading: boolean
  profile: Profile | null
  profiles: Profile[]
  partner: Profile | null
  pairingMode: PairingMode
  onboarded: boolean
  createProfile: (input: { displayName: string; stage: Stage; locale?: 'id' | 'en' }) => Promise<Profile>
  switchProfile: (id: string) => void
  setStage: (stage: Stage) => Promise<void>
  setPairingMode: (mode: PairingMode) => Promise<void>
  finishOnboarding: () => void
  refresh: () => Promise<void>
}

const SessionContext = createContext<SessionValue | null>(null)

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [loading, setLoading] = useState(true)
  const [profiles, setProfiles] = useState<Profile[]>([])
  const [activeId, setActiveId] = useState<string | null>(() =>
    localStorage.getItem(ACTIVE_PROFILE_KEY),
  )
  const [pairingMode, setPairingModeState] = useState<PairingMode>('solo')
  const [onboarded, setOnboarded] = useState(() => localStorage.getItem(ONBOARDED_KEY) === '1')

  const refresh = useCallback(async () => {
    const [rows, pairs] = await Promise.all([db.profiles.toArray(), db.pairs.toArray()])
    setProfiles(rows)
    setPairingModeState(pairs.find((p) => p.status === 'active')?.pairingMode ?? 'solo')
    setActiveId((current) => {
      if (current && rows.some((r) => r.id === current)) return current
      const next = rows[0]?.id ?? null
      if (next) localStorage.setItem(ACTIVE_PROFILE_KEY, next)
      return next
    })
  }, [])

  useEffect(() => {
    refresh().finally(() => setLoading(false))
  }, [refresh])

  const profile = useMemo(
    () => profiles.find((p) => p.id === activeId) ?? null,
    [profiles, activeId],
  )
  const partner = useMemo(
    () => profiles.find((p) => p.id !== activeId) ?? null,
    [profiles, activeId],
  )

  const createProfile: SessionValue['createProfile'] = useCallback(
    async ({ displayName, stage, locale = 'id' }) => {
      const now = new Date().toISOString()
      const p: Profile = {
        id: newId(),
        displayName: displayName.trim() || 'Aku',
        stage,
        locale,
        createdAt: now,
        stageHistory: [{ stage, changedAt: now }],
      }
      await db.profiles.add(p)
      localStorage.setItem(ACTIVE_PROFILE_KEY, p.id)
      setActiveId(p.id)
      await refresh()
      return p
    },
    [refresh],
  )

  const switchProfile = useCallback((id: string) => {
    localStorage.setItem(ACTIVE_PROFILE_KEY, id)
    setActiveId(id)
  }, [])

  /**
   * Stage changes are append-only (SHELL-02). Nothing is deleted, nothing is
   * archived away — only which panels the navigation puts in front of you.
   */
  const setStage = useCallback(
    async (stage: Stage) => {
      if (!profile || profile.stage === stage) return
      const history = [...profile.stageHistory, { stage, changedAt: new Date().toISOString() }]
      await db.profiles.update(profile.id, { stage, stageHistory: history })
      await logAudit({
        actorProfileId: profile.id,
        action: 'stage_change',
        objectStore: 'profiles',
        objectId: profile.id,
        summary: `${profile.stage} → ${stage}`,
      })
      await refresh()
    },
    [profile, refresh],
  )

  const setPairingMode = useCallback(
    async (mode: PairingMode) => {
      const existing = (await db.pairs.toArray()).find((p) => p.status === 'active')
      const memberIds = (await db.profiles.toArray()).map((p) => p.id)
      if (existing) await db.pairs.update(existing.id, { pairingMode: mode, memberProfileIds: memberIds })
      else
        await db.pairs.add({
          id: newId(),
          memberProfileIds: memberIds,
          pairingMode: mode,
          status: 'active',
          createdAt: new Date().toISOString(),
        })
      setPairingModeState(mode)
    },
    [],
  )

  const finishOnboarding = useCallback(() => {
    localStorage.setItem(ONBOARDED_KEY, '1')
    setOnboarded(true)
  }, [])

  const value: SessionValue = {
    loading,
    profile,
    profiles,
    partner,
    pairingMode,
    onboarded,
    createProfile,
    switchProfile,
    setStage,
    setPairingMode,
    finishOnboarding,
    refresh,
  }
  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>
}

export function useSession(): SessionValue {
  const ctx = useContext(SessionContext)
  if (!ctx) throw new Error('useSession dipakai di luar SessionProvider')
  return ctx
}

/** Convenience for feature code that cannot render without a profile. */
export function useProfileId(): string {
  const { profile } = useSession()
  if (!profile) throw new Error('Belum ada profil aktif')
  return profile.id
}
