import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import App from './app/App'
import './design-system/app.css'
import { registerSW } from 'virtual:pwa-register'

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
)

/**
 * Update flow (blueprint 06 §3): we never swap the running app underneath the
 * user mid-edit. A new version waits behind a prompt they choose to accept.
 */
const updateSW = registerSW({
  onNeedRefresh() {
    window.dispatchEvent(new CustomEvent('temudua:update-ready', { detail: { updateSW } }))
  },
})
