/**
 * The TemuDua mark.
 *
 * Two rounded shapes lean in and overlap, like a Venn diagram — and the
 * overlap is a heart. That is the product in one picture: two separate people,
 * and the thing they make where they meet. "Temu" = meet, "dua" = two.
 *
 * Why this and not the previous mark: the old one was two crossing ribbons,
 * which was pretty but abstract — you had to be told what it meant, and at
 * 16px it read as a squiggle. This one is legible at favicon size, obviously
 * about *two* of something, and the heart appears without being drawn as a
 * cliché heart outline.
 *
 * The heart is real geometry, not a pasted-on shape: it is the intersection of
 * the two circles, cut with a clip path. Move either circle and the heart
 * changes with them, which is the whole idea.
 */

export interface LogoProps {
  size?: number
  /** `plain` = mark only on transparent. `tile` = rounded app-icon tile. */
  variant?: 'plain' | 'tile'
  /** Decorative by default; give a label when it stands alone as a link. */
  label?: string
  className?: string
}

export function Logo({ size = 32, variant = 'plain', label, className }: LogoProps) {
  // Ids must be unique per instance or two logos on one page share defs and the
  // second one renders with the first one's clip.
  const uid = `lg${variant}`
  const inset = variant === 'tile' ? 14 : 2

  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 96 96"
      fill="none"
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      <defs>
        <linearGradient id={`${uid}-bg`} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#FFF3F8" />
          <stop offset="50%" stopColor="#F3EEFF" />
          <stop offset="100%" stopColor="#DFF8F4" />
        </linearGradient>
        <linearGradient id={`${uid}-l`} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#FFA6C4" />
          <stop offset="100%" stopColor="#FF6F9F" />
        </linearGradient>
        <linearGradient id={`${uid}-r`} x1="100%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="#6FE0D0" />
          <stop offset="100%" stopColor="#2FBFB0" />
        </linearGradient>
        <linearGradient id={`${uid}-heart`} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#FFD05C" />
          <stop offset="100%" stopColor="#FF9A3D" />
        </linearGradient>
      </defs>

      {variant === 'tile' && <rect width="96" height="96" rx="24" fill={`url(#${uid}-bg)`} />}

      <g transform={variant === 'tile' ? `translate(48 49) scale(${1 - inset / 96}) translate(-48 -49)` : ''}>
        {/* Two people, leaning toward each other. Equal size — neither is the
            main one. `mix-blend-multiply` lets the overlap darken naturally so
            the shapes read as translucent rather than stacked. */}
        <circle cx="36" cy="50" r="26" fill={`url(#${uid}-l)`} />
        <circle cx="60" cy="50" r="26" fill={`url(#${uid}-r)`} opacity="0.92" />

        {/* The heart sits in the lens, sized to fit inside it.
            The lens is 28 wide and 46 tall (circles r=26, centres 24 apart), so
            a 26-wide heart centred on (48, 50) lands fully inside. An earlier
            version was bigger and low, so the lens clipped its right shoulder
            and it read as a rendering bug rather than a shape. */}
        <path
          d="M48 61c-8-5.6-13-9.8-13-15.2a6.8 6.8 0 0 1 13-3.3 6.8 6.8 0 0 1 13 3.3C61 51.2 56 55.4 48 61Z"
          fill={`url(#${uid}-heart)`}
        />
      </g>
    </svg>
  )
}
