/**
 * Feature message bundles.
 *
 * The core dictionary (`id.ts` / `en.ts`) covers the shell and the original
 * modules. Everything built after that ships its own `messages.ts` inside its
 * feature folder and is registered here — one import line per feature.
 *
 * This exists so several people (or agents) can add features in parallel
 * without every one of them editing the same 900-line dictionary and
 * conflicting. The parity test in `i18n.test.ts` covers these bundles too, so a
 * missing English string is still a build-time failure.
 */

export interface MessageBundle {
  readonly id: Readonly<Record<string, string>>
  readonly en: Readonly<Record<string, string>>
}

import { wishlist } from '@/features/wishlist/messages'
import { dates } from '@/features/dates/messages'
import { timeline } from '@/features/timeline/messages'
import { finance2 } from '@/features/finance/messages'
import { wedding2 } from '@/features/wedding/messages'
import { fertility } from '@/features/fertility/messages'
import { coparenting } from '@/features/coparenting/messages'
import { chores } from '@/features/chores/messages'
import { calendar2 } from '@/features/calendar/messages'
import { sync } from '@/features/sync/messages'
import { cards } from '@/features/cards/messages'
import { cycle2 } from '@/features/cycle/messages'

export const BUNDLES = {
  wishlist,
  dates,
  timeline,
  finance2,
  wedding2,
  fertility,
  coparenting,
  chores,
  calendar2,
  sync,
  cards,
  cycle2,
} as const

export type FeatureMessageKey =
  | keyof typeof wishlist.id
  | keyof typeof dates.id
  | keyof typeof timeline.id
  | keyof typeof finance2.id
  | keyof typeof wedding2.id
  | keyof typeof fertility.id
  | keyof typeof coparenting.id
  | keyof typeof chores.id
  | keyof typeof calendar2.id
  | keyof typeof sync.id
  | keyof typeof cards.id
  | keyof typeof cycle2.id

function merge(locale: 'id' | 'en'): Record<string, string> {
  const out: Record<string, string> = {}
  for (const bundle of Object.values(BUNDLES)) Object.assign(out, bundle[locale])
  return out
}

export const featureId = merge('id')
export const featureEn = merge('en')
