/**
 * TemuDua domain model.
 *
 * Source of truth: blueprint 06 §5–7 (data model, envelope, stores) and
 * blueprint 05 §2–3 (data classification, visibility states).
 *
 * Every sensitive record carries an ownership envelope. Ownership is decided at
 * write time, never inferred at read time — that is what makes "private by
 * default" checkable in a test instead of a promise in a doc.
 */

export const SCHEMA_VERSION = 5

/** Blueprint 02 §3 — lifecycle stages. Changing stage never deletes data. */
export type Stage = 'single' | 'dating' | 'married'
export const STAGES: readonly Stage[] = ['single', 'dating', 'married']

/** Blueprint 05 §3 — visibility states, in escalating disclosure order. */
export type Visibility =
  | 'private' // only owner
  | 'self_reflection' // private, counted in owner's own trends
  | 'share_later' // owner drafted it to share, has not released it
  | 'shared' // partner can see it
  | 'professional_only' // scoped, time-bound referral packet
  | 'both_partners' // co-owned object

export const VISIBILITIES: readonly Visibility[] = [
  'private',
  'self_reflection',
  'share_later',
  'shared',
  'professional_only',
  'both_partners',
]

/** Visibility states where a non-owner partner may read the record body. */
const PARTNER_READABLE: ReadonlySet<Visibility> = new Set<Visibility>(['shared', 'both_partners'])

export type ApprovalStatus =
  | 'not_required'
  | 'pending'
  | 'approved'
  | 'rejected'
  | 'revoked'

/** Blueprint 05 §2 — data classification, drives default visibility and export rules. */
export type DataClass =
  | 'C0_config'
  | 'C1_personal'
  | 'C2_shared_ops'
  | 'C3_relationship'
  | 'C4_health'
  | 'C5_safety'
  | 'C6_professional'

/** Blueprint 06 §6 — ownership-aware object envelope. */
export interface Envelope {
  id: string
  schemaVersion: number
  ownerProfileId: string
  coOwnerProfileIds: string[]
  dataClass: DataClass
  visibility: Visibility
  approvalStatus: ApprovalStatus
  /** Explicit grants. Empty for `private`; filled when the owner shares. */
  sharedWithProfileIds: string[]
  /** ISO 8601. Professional packets expire; everything else leaves this undefined. */
  sharedUntil?: string
  createdAt: string
  updatedAt: string
  /** Soft delete. Permanent erase is a separate, explicit flow (blueprint 05 §5). */
  deletedAt?: string
  revokedAt?: string
  /** Optimistic-concurrency counter for the future sync layer (blueprint 06 §11). */
  version: number
  /**
   * Set only on records created by the sample-data loader in Settings.
   *
   * It exists so removing the sample data can delete exactly those rows and
   * leave anything the couple wrote themselves alone — someone who tries the
   * demo and then starts using the app for real must not lose their entries.
   */
  demo?: true
}

export type Owned<T> = Envelope & T

/**
 * The one read gate. Every query path must route through this — that is the
 * whole privacy model, and `visibility.test.ts` is what keeps it honest.
 */
export function canRead(env: Envelope, viewerProfileId: string): boolean {
  if (env.deletedAt) return false
  if (env.ownerProfileId === viewerProfileId) return true
  if (env.coOwnerProfileIds.includes(viewerProfileId)) return true
  if (env.revokedAt) return false
  if (env.visibility === 'professional_only') {
    // Professional packets are scoped and time-bound; a partner is not a clinician.
    return (
      env.sharedWithProfileIds.includes(viewerProfileId) && !isExpired(env)
    )
  }
  if (!PARTNER_READABLE.has(env.visibility)) return false
  if (isExpired(env)) return false
  // `shared` with no explicit grant list means "shared with the pair".
  return (
    env.sharedWithProfileIds.length === 0 ||
    env.sharedWithProfileIds.includes(viewerProfileId)
  )
}

function isExpired(env: Envelope): boolean {
  return env.sharedUntil !== undefined && env.sharedUntil <= new Date().toISOString()
}

/** Only the owner may change visibility (blueprint 05 §4). Co-owners may not. */
export function canChangeVisibility(env: Envelope, actorProfileId: string): boolean {
  return env.ownerProfileId === actorProfileId
}

/** Blueprint 05 §2 — default visibility per class. Used on every create. */
export const DEFAULT_VISIBILITY: Record<DataClass, Visibility> = {
  C0_config: 'shared',
  C1_personal: 'private',
  C2_shared_ops: 'shared',
  C3_relationship: 'private',
  C4_health: 'private',
  C5_safety: 'private',
  C6_professional: 'professional_only',
}

// ---------------------------------------------------------------------------
// Entities
// ---------------------------------------------------------------------------

export interface Profile {
  id: string
  displayName: string
  stage: Stage
  locale: 'id' | 'en'
  /** Optional per-profile PIN, stored only as a PBKDF2 hash (see security/pin.ts). */
  pinHash?: string
  pinSalt?: string
  createdAt: string
  /** Append-only stage history — switching stage must never lose the past. */
  stageHistory: { stage: Stage; changedAt: string }[]
}

export type PairingMode = 'solo' | 'same_device' | 'paired_export'

export interface Pair {
  id: string
  memberProfileIds: string[]
  pairingMode: PairingMode
  status: 'active' | 'uncoupled'
  createdAt: string
  /** Sync cutoff written at unpair; nothing after it crosses the boundary. */
  uncoupledAt?: string
}

/** REL-01. Energy/connection are 1–5 self-reports, never combined into one score. */
export type CheckIn = Owned<{
  kind: 'checkin'
  date: string
  energy: 1 | 2 | 3 | 4 | 5
  connection: 1 | 2 | 3 | 4 | 5
  stressContext?: string
  note?: string
}>

/** REL-02 — "hal yang belum sempat dibahas". */
export type Need = Owned<{
  kind: 'need'
  text: string
  category?: string
  resolvedAt?: string
}>

/** REL-04 */
export type Appreciation = Owned<{
  kind: 'appreciation'
  text: string
  sentAt?: string
}>

/** REL-03 */
export type Topic = Owned<{
  kind: 'topic'
  title: string
  note?: string
  status: 'open' | 'scheduled' | 'talked' | 'parked'
  scheduledAt?: string
}>

/** REL-05. Status never encodes blame. */
export type RepairRequest = Owned<{
  kind: 'repair'
  message: string
  status: 'waiting' | 'accepted' | 'scheduled' | 'complete' | 'postponed'
  scheduledAt?: string
  postponeReason?: string
}>

export type EventType =
  | 'date'
  | 'task'
  | 'bill'
  | 'family'
  | 'me_time'
  | 'health'
  | 'celebration'
  | 'private'

/** CAL-01/02 */
export type CalendarEvent = Owned<{
  kind: 'event'
  title: string
  date: string // yyyy-MM-dd
  time?: string // HH:mm
  type: EventType
  note?: string
  /** Shown to a partner instead of `title` when the event is private. */
  maskedTitle?: string
  recurrence?: Recurrence
}>

export interface Recurrence {
  freq: 'daily' | 'weekly' | 'monthly' | 'yearly'
  interval: number
  until?: string
}

/** HOME-01/02. `mentalLoadType` is the point: doing is only the last step. */
export type MentalLoadType = 'notice' | 'remember' | 'plan' | 'coordinate' | 'do'
export const MENTAL_LOAD_TYPES: readonly MentalLoadType[] = [
  'notice',
  'remember',
  'plan',
  'coordinate',
  'do',
]

export type Task = Owned<{
  kind: 'task'
  title: string
  /** Exactly one accountable person. "Kita" is not an owner (HOME-01). */
  accountableProfileId: string
  helperProfileIds: string[]
  mentalLoadType: MentalLoadType
  dueDate?: string
  status: 'todo' | 'doing' | 'done'
  completedAt?: string
  recurrence?: Recurrence
  note?: string
}>

/** FIN-01/02/04 */
export type SplitModel = 'equal' | 'proportional' | 'alternating' | 'custom'

export type Bill = Owned<{
  kind: 'bill'
  title: string
  amount: number
  currency: 'IDR'
  dueDate: string
  payerProfileId: string
  splitModel: SplitModel
  /** profileId → share in 0..1. Must sum to 1 when splitModel is 'custom'. */
  splitShares?: Record<string, number>
  status: 'unpaid' | 'paid'
  paidAt?: string
  /** Money space: personal money stays invisible to a partner (FIN-01). */
  space: 'mine' | 'partner' | 'shared'
  installmentOf?: { total: number; index: number }
}>

/** MEM-01 */
export type Memory = Owned<{
  kind: 'memory'
  title: string
  date: string
  story?: string
  isMilestone: boolean
}>

/** CAL-05. Owned by the person whose body it is. Never auto-shared. */
export type CycleLog = Owned<{
  kind: 'cycle'
  startDate: string
  /** Bleeding days. Undefined while the period is still ongoing. */
  durationDays?: number
  symptoms: string[]
  energy?: 1 | 2 | 3 | 4 | 5
  pain?: 1 | 2 | 3 | 4 | 5
  note?: string
  /** Owner-written, e.g. "dua hari pertama aku lebih butuh istirahat". */
  supportPreference?: string
}>

/**
 * One day of cycle tracking — the daily half of the module.
 *
 * `CycleLog` records a *period* (it starts, it lasts n days). This records a
 * *day*: what was felt, what was seen, what was measured. They are separate
 * records because they answer separate questions and because a person may want
 * to log a symptom on a day with no bleeding at all.
 *
 * `date` is the natural key — one row per calendar day — so re-logging a day
 * updates it instead of stacking duplicates.
 */
export type CycleDay = Owned<{
  kind: 'cycleDay'
  /** `yyyy-MM-dd`. One row per day. */
  date: string
  /** Bleeding seen that day. `none` is a real answer, not a missing one. */
  flow?: 'none' | 'spotting' | 'light' | 'medium' | 'heavy'
  /** Ids from `SYMPTOM_GROUPS` in the cycle feature. Free of any diagnosis. */
  symptoms: string[]
  mood?: string[]
  /** Cervical mucus, in the words people actually use. */
  discharge?: 'kering' | 'lengket' | 'krim' | 'bening' | 'tidak dicek'
  /** Basal body temperature in °C, as typed. Never averaged into advice. */
  temperature?: number
  /** Whether sex happened, and whether protection was used. Owner-only detail. */
  intimacy?: 'tidak' | 'ya' | 'ya_pengaman'
  /** An ovulation predictor kit result, if the person uses one. */
  opk?: 'negatif' | 'positif' | 'tidak dicek'
  energy?: 1 | 2 | 3 | 4 | 5
  pain?: 1 | 2 | 3 | 4 | 5
  note?: string
}>

/**
 * TRUST-03 — append-only. Never edited, never deleted by app code.
 * `seq` is a monotonic auto-increment key so the log always reads back in the
 * order it was written; timestamps alone tie within the same millisecond.
 */
export interface AuditEvent {
  seq?: number
  actorProfileId: string
  action:
    | 'create'
    | 'update'
    | 'delete'
    | 'share'
    | 'revoke'
    | 'restore'
    | 'export'
    | 'stage_change'
    | 'unpair'
  objectStore: string
  objectId: string
  /** Never the record body — an audit log must not become a second data leak. */
  summary: string
  timestamp: string
}

export type SensitiveRecord =
  | GroceryItem
  | HouseholdDocument
  | EmergencyContact
  | SharedGoal
  | MoneyMeeting
  | WeddingRecord
  | FamilyRecord
  | CheckIn
  | Need
  | Appreciation
  | Topic
  | RepairRequest
  | CalendarEvent
  | Task
  | Bill
  | Memory
  | CycleLog
  | CycleDay

// ---------------------------------------------------------------------------
// Phase 9 — Wedding (WED-01..05)
//
// Readiness and party planning are deliberately different `kind`s in one store:
// blueprint 03 §7 requires the two workspaces stay separate in the UI, but they
// share the same envelope, the same audit trail, and the same export path.
// ---------------------------------------------------------------------------

/** WED-02 — the eight readiness areas. Answers are private until shared. */
export type ReadinessArea =
  | 'values'
  | 'money'
  | 'family'
  | 'career'
  | 'children'
  | 'health'
  | 'conflict'
  | 'intimacy'

export const READINESS_AREAS: readonly ReadinessArea[] = [
  'values',
  'money',
  'family',
  'career',
  'children',
  'health',
  'conflict',
  'intimacy',
]

export type WeddingRecord = Owned<
  | {
      kind: 'readiness'
      area: ReadinessArea
      prompt: string
      answer: string
      /** Owner's own sense of where they are — never compared automatically. */
      stance: 'belum' | 'lagi dipikir' | 'udah jelas'
    }
  | {
      kind: 'wedding_task'
      title: string
      accountableProfileId: string
      dueDate?: string
      status: 'todo' | 'doing' | 'done'
      phase: 'jauh_hari' | 'sebulan' | 'seminggu' | 'hari_h'
      note?: string
    }
  | {
      kind: 'vendor'
      name: string
      category: string
      /** Where the contact came from — no marketplace, no affiliate lock-in. */
      sourceNote?: string
      contact?: string
      quotedPrice?: number
      status: 'dilirik' | 'ditanya' | 'deal' | 'batal'
    }
  | {
      kind: 'guest'
      name: string
      side: 'aku' | 'pasangan' | 'bersama'
      seats: number
      status: 'draft' | 'diundang' | 'hadir' | 'nggak_hadir'
    }
  | {
      kind: 'wedding_budget'
      label: string
      planned: number
      paid: number
      dueDate?: string
    }
>

// ---------------------------------------------------------------------------
// Phase 10 — Fertility, pregnancy, child, co-parenting (FAM-01..06)
//
// Everything here is opt-in and health-classified. Child records are shared by
// default between the people raising the child; the pregnant person's own body
// data is not.
// ---------------------------------------------------------------------------

export type FamilyRecord = Owned<
  | {
      kind: 'pregnancy'
      /** First day of the last menstrual period — the only date we compute from. */
      lmpDate: string
      note?: string
      status: 'jalan' | 'selesai'
    }
  | {
      kind: 'appointment'
      title: string
      date: string
      time?: string
      place?: string
      /** Written by the user before the visit; the app never generates these. */
      questions: string[]
      note?: string
    }
  | {
      kind: 'birth_plan'
      preference: string
      note?: string
    }
  | {
      kind: 'support_request'
      /** FAM-04 — a specific action, not a mood report. */
      action: string
      status: 'diminta' | 'diambil' | 'selesai'
      forProfileId?: string
    }
  | {
      kind: 'child'
      name: string
      birthDate: string
      note?: string
    }
  | {
      kind: 'growth'
      childId: string
      date: string
      weightKg?: number
      heightCm?: number
      headCm?: number
      note?: string
    }
  | {
      kind: 'immunization'
      childId: string
      vaccine: string
      /** Planned or given — the app reminds, it does not schedule medicine. */
      date: string
      given: boolean
      note?: string
    }
  | {
      kind: 'shift'
      childId?: string
      date: string
      from: string
      to: string
      caregiverProfileId: string
      handoverNote?: string
    }
>

// ---------------------------------------------------------------------------
// Household extras (HOME-03/04/05) and shared finance (FIN-03, HOME-06)
//
// Each of these is a small store rather than another discriminated union: they
// have genuinely different shapes and different indexes, and lumping them
// together would mean every query filtering on `kind` first.
// ---------------------------------------------------------------------------

/** HOME-03 — a shared shopping list; whoever adds need not be whoever buys. */
export type GroceryItem = Owned<{
  kind: 'grocery'
  name: string
  quantity?: string
  /** Who usually picks this up. Not an assignment — a hint. */
  usualBuyerProfileId?: string
  bought: boolean
  boughtAt?: string
}>

export type DocumentKind =
  | 'vehicle'
  | 'identity'
  | 'insurance'
  | 'tax'
  | 'warranty'
  | 'contract'
  | 'other'

export const DOCUMENT_KINDS: readonly DocumentKind[] = [
  'vehicle',
  'identity',
  'insurance',
  'tax',
  'warranty',
  'contract',
  'other',
]

/**
 * HOME-04 — metadata only, never the document itself.
 *
 * TemuDua deliberately stores no scans and no attachments: an ID photo sitting
 * in a shared-phone database is a liability the app has no way to protect.
 */
export type HouseholdDocument = Owned<{
  kind: 'document'
  name: string
  docKind: DocumentKind
  /** Optional and warned about in the UI — a shared device may be watched. */
  reference?: string
  expiresAt?: string
  note?: string
}>

/** HOME-05 — reachable offline, which is the entire point. */
export type EmergencyContact = Owned<{
  kind: 'contact'
  name: string
  relation: string
  phone: string
  note?: string
}>

/** HOME-06 — a goal always carries its next concrete action, never just a bar. */
export type SharedGoal = Owned<{
  kind: 'goal'
  title: string
  targetAmount: number
  savedAmount: number
  /** "Pindahin 500rb tiap tanggal 5", not "nabung lebih rajin". */
  nextAction?: string
  targetDate?: string
  achievedAt?: string
}>

/** FIN-03 — the monthly money conversation, with an agenda built from real data. */
export type MoneyMeeting = Owned<{
  kind: 'meeting'
  date: string
  /** Counts captured at the time, so past meetings stay meaningful. */
  agenda: { bills: number; goals: number; topics: number }
  notes?: string
}>

// ---------------------------------------------------------------------------
// Wishlist (v4)
//
// A *reservation* is a separate record owned by whoever reserved, left at the
// C3 default (`private`), so `canRead()` hides the surprise from the wish's
// owner. Putting `reservedBy` on the wish itself would leak it into the owner's
// own row, their backup, and their export.
// ---------------------------------------------------------------------------

export type Urgency = 'kapan_kapan' | 'lagi_pengin' | 'lagi_butuh'

/** Which of the three lists a wish belongs to. */
export type WishScope = 'sendiri' | 'bareng'

export type WishRecord = Owned<
  | {
      kind: 'wish'
      title: string
      note?: string
      /** Rupiah, typed by a human as a guess. Never fetched, never a real price. */
      priceEstimate?: number
      link?: string
      urgency: Urgency
      scope: WishScope
      /** Set by the owner when they got it — however they got it. */
      fulfilledAt?: string
    }
  | {
      kind: 'reservation'
      wishId: string
      status: 'diambil' | 'sudah_dikasih'
    }
>

export type Wish = Extract<WishRecord, { kind: 'wish' }>
export type Reservation = Extract<WishRecord, { kind: 'reservation' }>
