/** Every icon name, for the gallery and for the consistency test. */
export const ICON_NAMES = Object.keys(P) as IconName[]

/** Exposed so the gallery and the motion test can read the pairing table. */
export const ICON_MOTION: Readonly<Record<IconName, string>> = MOTION

export interface IconProps {
  name: IconName
  size?: number
  /** Give a label when the icon carries meaning on its own; omit when text is adjacent. */
  label?: string
  className?: string
  /** Turns the motion on. Off by default so lists of icons stay still. */
  animate?: boolean
}

export function Icon({ name, size = 22, label, className, animate = false }: IconProps) {
  const motion = animate ? MOTION[name] : ''
  return (
    <svg
      className={['ic', motion, className].filter(Boolean).join(' ')}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.7}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      {P[name]}
    </svg>
  )
}
