import { useMemo } from 'react'
import { Link } from 'react-router-dom'
import { useLiveQuery } from 'dexie-react-hooks'
import { differenceInCalendarDays, parseISO } from 'date-fns'
import { Icon, type IconName } from '@/design-system/Icon'
import { db } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n, type MessageKey } from '@/i18n'
import { formatRupiah } from '@/i18n/format'
import { computeStreak, type DayRecord } from '@/features/companion/streak'
import { growth } from '@/features/companion/model'
import { monthKey, monthView } from '@/features/finance/monthly'
import type { CalendarEvent } from '@/types/domain'
import type { LedgerEntry } from '@/features/finance/store'
import './mainfeatures.css'

/**
 * The four things this app is for, on the first screen, with today's number on
 * them.
 *
 * They were reachable — from a directory called "Semua", next to eleven other
 * modules, which is a filing cabinet, not a front page. A feature listed
 * alphabetically among fifteen reads as an also-ran no matter how much work is
 * behind it.
 *
 * Each tile carries one live line rather than a description, because "Rp
 * 2.758.000 left this month" is an invitation and "track your household
 * finances" is a brochure. The line is always a fact the couple typed in
 * themselves: no target, no comparison between the two of them, no judgement.
 */

interface Tile {
  to: string
  label: MessageKey
  icon: IconName
  tone: string
  /** Today's number, already formatted. Falls back to an invitation. */
  line: string
}

/** Temu's stage and streak, read the same way the Temu screen reads them. */
function useTemuLine(): string | null {
  const { t } = useI18n()
  const state = useLiveQuery(async () => {
    const [records, meta] = await Promise.all([
      db.settings.get('temu.days'),
      db.settings.get('temu.meta'),
    ])
    return {
      days: (records?.value as DayRecord[]) ?? [],
      startedAt: (meta?.value as { startedAt?: string } | undefined)?.startedAt,
    }
  }, [])
  if (!state) return null
  const streak = computeStreak(state.days, new Date())
  const relDays = state.startedAt
    ? differenceInCalendarDays(new Date(), parseISO(state.startedAt))
    : streak.pairDays
  const g = growth(streak.pairDays, relDays)
  if (streak.pairDays === 0) return t('home.temuNew')
  return t('home.temuLine', { stage: t(g.stage.name), n: streak.current })
}

export default function MainFeatures({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const today = new Date().toISOString().slice(0, 10)

  const events = useOwned<CalendarEvent>('events', me)
  const ledger = useOwned<LedgerEntry>('ledger', me)
  const temuLine = useTemuLine()

  const nextEvent = useMemo(
    () =>
      (events ?? [])
        .filter((e) => e.date >= today)
        .sort((a, b) => a.date.localeCompare(b.date))[0],
    [events, today],
  )

  const left = useMemo(() => {
    const rows = (ledger ?? []).map((e) => ({
      id: e.id,
      label: e.label,
      amount: e.amount,
      category: e.category,
      date: e.date,
      planned: e.planned,
      ownerProfileId: e.ownerProfileId,
    }))
    return monthView(rows, monthKey(today))
  }, [ledger, today])

  const tiles: Tile[] = [
    {
      to: '/kalender',
      label: 'nav.calendar',
      icon: 'calendar',
      tone: 'pink',
      line: nextEvent
        ? t('home.calendarNext', { title: nextEvent.title })
        : t('home.calendarEmpty'),
    },
    {
      to: '/uang',
      label: 'finance2.title',
      icon: 'money',
      tone: 'amber',
      // Nothing logged yet reads as an invitation, not as "Rp 0" — a zero here
      // looks like an answer about their money, and it is not one.
      line:
        left.entries.length > 0
          ? t('home.moneyLeft', { amount: formatRupiah(left.left, locale) })
          : t('home.moneyEmpty'),
    },
    {
      to: '/temu',
      label: 'temu.title',
      icon: 'temu',
      tone: 'teal',
      line: temuLine ?? t('home.temuNew'),
    },
    {
      to: '/kartu',
      label: 'cards.title',
      icon: 'cards',
      tone: 'violet',
      line: t('home.cardsLine'),
    },
  ]

  return (
    <nav className="mainfeat" aria-label={t('home.mainFeatures')}>
      {tiles.map((tile) => (
        <Link key={tile.to} to={tile.to} className={`mainfeat__tile mainfeat__tile--${tile.tone}`}>
          <span className="mainfeat__ic">
            <Icon name={tile.icon} size={22} animate />
          </span>
          <strong className="mainfeat__label">{t(tile.label)}</strong>
          <small className="mainfeat__line">{tile.line}</small>
          <Icon name="chevron-right" size={16} className="mainfeat__go" />
        </Link>
      ))}
    </nav>
  )
}
