import { useEffect, useId, useRef } from 'react'
import { Icon, type IconName } from '@/design-system/Icon'
import { Sticker, type StickerName } from '@/design-system/Decor'
import type { Visibility } from '@/types/domain'
import { useT } from '@/i18n'

export function Card({
  title,
  icon,
  action,
  hint,
  children,
}: {
  title?: string
  icon?: IconName
  action?: React.ReactNode
  hint?: string
  children?: React.ReactNode
}) {
  return (
    <section className="card stack stack--tight">
      {(title || action) && (
        <div className="card__head">
          <h2 className="card__title">
            {icon && <Icon name={icon} size={20} />}
            {title}
          </h2>
          {action}
        </div>
      )}
      {hint && <p className="card__hint">{hint}</p>}
      {children}
    </section>
  )
}

/**
 * Empty state. Pass a `sticker` when the screen is genuinely empty on first
 * visit — a drawn scene is the difference between "you haven't started yet" and
 * "this app is broken". Keep the plain `icon` form for empties that appear
 * mid-flow (a filter matched nothing), where a big illustration overstates it.
 */
export function EmptyState({
  icon = 'info',
  sticker,
  title,
  hint,
  action,
}: {
  icon?: IconName
  sticker?: StickerName
  title: string
  hint?: string
  action?: React.ReactNode
}) {
  if (sticker) {
    return (
      <div className="empty-art">
        <Sticker name={sticker} size={104} />
        <strong className="empty-art__title">{title}</strong>
        {hint && <p className="empty-art__body">{hint}</p>}
        {action}
      </div>
    )
  }
  return (
    <div className="empty">
      <Icon name={icon} size={32} />
      <div className="stack stack--tight">
        <strong style={{ color: 'var(--ink)' }}>{title}</strong>
        {hint && <span style={{ fontSize: 13 }}>{hint}</span>}
      </div>
      {action}
    </div>
  )
}

const VISIBILITY_UI: Record<Visibility, { icon: IconName; chip: string }> = {
  private: { icon: 'private', chip: 'chip' },
  self_reflection: { icon: 'self', chip: 'chip' },
  share_later: { icon: 'consent', chip: 'chip--yellow' },
  shared: { icon: 'shared', chip: 'chip--blue' },
  professional_only: { icon: 'referral', chip: 'chip--lavender' },
  both_partners: { icon: 'shared', chip: 'chip--mint' },
}

/** Every sensitive object shows its state — icon + word, never colour alone. */
export function VisibilityBadge({ visibility }: { visibility: Visibility }) {
  const t = useT()
  const ui = VISIBILITY_UI[visibility]
  return (
    <span className={`chip ${ui.chip}`}>
      <Icon name={ui.icon} size={14} />
      {t(`vis.${visibility}` as const)}
    </span>
  )
}

/** Options the owner can pick from. Labels resolve through `t()` at render. */
export const VISIBILITY_OPTIONS = [
  'private',
  'share_later',
  'shared',
  'professional_only',
] as const

/** The subset offered when a professional packet makes no sense (most screens). */
export const PARTNER_VISIBILITY_OPTIONS = ['private', 'share_later', 'shared'] as const

/** Bottom sheet on mobile, centred dialog on desktop. Native <dialog> gives us
 *  the focus trap, Escape handling, and inert background for free. */
export function Sheet({
  open,
  onClose,
  title,
  children,
}: {
  open: boolean
  onClose: () => void
  title: string
  children: React.ReactNode
}) {
  const t = useT()
  const ref = useRef<HTMLDialogElement>(null)
  const titleId = useId()

  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (open && !el.open) el.showModal()
    if (!open && el.open) el.close()
  }, [open])

  // The <dialog> stays mounted and is closed through the effect. Unmounting an
  // open modal leaves it in the browser's top layer, which keeps the rest of the
  // page inert — a closed sheet would silently freeze the screen behind it.
  return (
    <dialog
      ref={ref}
      className="dialog"
      aria-labelledby={titleId}
      onClose={onClose}
      onClick={(e) => {
        if (e.target === ref.current) onClose()
      }}
    >
      {open && (
      <div className="dialog__body stack">
        <div className="row row--between">
          <h2 id={titleId}>{title}</h2>
          <button type="button" className="btn btn--ghost btn--sm" onClick={onClose}>
            <Icon name="close" size={18} label={t('common.close')} />
          </button>
        </div>
        {children}
      </div>
      )}
    </dialog>
  )
}

export function Field({
  label,
  hint,
  error,
  children,
}: {
  label: string
  hint?: string
  error?: string
  children: (props: { id: string; 'aria-describedby'?: string; 'aria-invalid'?: boolean }) => React.ReactNode
}) {
  const id = useId()
  const hintId = `${id}-hint`
  const errId = `${id}-err`
  const describedBy = [hint ? hintId : null, error ? errId : null].filter(Boolean).join(' ')
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      {children({
        id,
        ...(describedBy ? { 'aria-describedby': describedBy } : {}),
        ...(error ? { 'aria-invalid': true } : {}),
      })}
      {hint && (
        <span className="field__hint" id={hintId}>
          {hint}
        </span>
      )}
      {error && (
        <span className="field__error" id={errId}>
          {error}
        </span>
      )}
    </div>
  )
}

/** 1–5 self-report. Labelled radiogroup so it reads correctly to a screen reader. */
export function Scale({
  legend,
  value,
  onChange,
  lowLabel,
  highLabel,
}: {
  legend: string
  value: number | undefined
  onChange: (v: 1 | 2 | 3 | 4 | 5) => void
  lowLabel: string
  highLabel: string
}) {
  return (
    <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
      <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{legend}</legend>
      <div className="scale" role="group">
        {([1, 2, 3, 4, 5] as const).map((n) => (
          <button
            key={n}
            type="button"
            aria-pressed={value === n}
            aria-label={`${legend}: ${n} dari 5`}
            onClick={() => onChange(n)}
          >
            {n}
          </button>
        ))}
      </div>
      <div className="row row--between" style={{ fontSize: 12, color: 'var(--muted)' }}>
        <span>{lowLabel}</span>
        <span>{highLabel}</span>
      </div>
    </fieldset>
  )
}
