import { lazy, Suspense } from 'react'
import { HashRouter, NavLink, Route, Routes, useLocation } from 'react-router-dom'
import { Icon } from '@/design-system/Icon'
import { Logo } from '@/design-system/Logo'
import { NAV_BY_STAGE, STAGE_LABEL } from './nav'
import { SessionProvider, useSession } from './session'
import { ThemeProvider } from './theme'
import Onboarding from '@/features/onboarding/Onboarding'
import Today from '@/features/today/Today'
import { I18nProvider, useT } from '@/i18n'

// Stage modules load on demand so a single user never downloads the parenting
// chunk (blueprint 06 §1, §12).
const Relationship = lazy(() => import('@/features/relationship/Relationship'))
const Calendar = lazy(() => import('@/features/calendar/Calendar'))
const Household = lazy(() => import('@/features/household/Household'))
const Moments = lazy(() => import('@/features/moments/Moments'))
const Cycle = lazy(() => import('@/features/cycle/Cycle'))
const Privacy = lazy(() => import('@/features/privacy/Privacy'))
const Family = lazy(() => import('@/features/family/Family'))
const Wedding = lazy(() => import('@/features/wedding/Wedding'))
const Settings = lazy(() => import('@/features/settings/Settings'))
const Help = lazy(() => import('@/features/referral/Help'))
const IconGallery = lazy(() => import('@/design-system/IconGallery'))
const Companion = lazy(() => import('@/features/companion/Companion'))
const Journey = lazy(() => import('@/features/companion/Journey'))
// Second-wave modules. None of them are on the shelf — it is full at five per
// stage — so they are reached from the Kehidupan hub (`nav.MODULE_LINKS`).
const Chores = lazy(() => import('@/features/chores/Index'))
const Finance = lazy(() => import('@/features/finance/Index'))
const Wishlist = lazy(() => import('@/features/wishlist/Index'))
const DateIdeas = lazy(() => import('@/features/dates/Index'))
const Timeline = lazy(() => import('@/features/timeline/Index'))
const Fertility = lazy(() => import('@/features/fertility/Index'))
const Coparenting = lazy(() => import('@/features/coparenting/Index'))
const Sync = lazy(() => import('@/features/sync/Index'))
const Cards = lazy(() => import('@/features/cards/Index'))
const AllModules = lazy(() => import('@/features/household/AllModules'))

function Nav() {
  const t = useT()
  const { profile } = useSession()
  if (!profile) return null
  const items = NAV_BY_STAGE[profile.stage]
  return (
    <nav className="nav" aria-label={t('app.mainNav')}>
      {items.map((item) => (
        <NavLink key={item.to} to={item.to} end={item.to === '/'} className="nav__item">
          {({ isActive }) => (
            <>
              <Icon name={item.icon} size={22} animate={isActive} />
              <span className="nav__label">{t(item.label)}</span>
            </>
          )}
        </NavLink>
      ))}
    </nav>
  )
}

function TopBar() {
  const t = useT()
  const { profile, profiles, switchProfile } = useSession()
  if (!profile) return null
  return (
    <header className="topbar">
      <Logo size={30} variant="tile" />
      <div className="grow">
        <div className="topbar__brand">{t('app.name')}</div>
        <span className="topbar__sub">{t(STAGE_LABEL[profile.stage])}</span>
      </div>
      {profiles.length > 1 && (
        <label className="row" style={{ gap: 6 }}>
          <span className="visually-hidden">{t('app.activeProfile')}</span>
          <Icon name="shared" size={18} />
          <select
            value={profile.id}
            onChange={(e) => switchProfile(e.target.value)}
            style={{ width: 'auto', minHeight: 36, fontSize: 13 }}
          >
            {profiles.map((p) => (
              <option key={p.id} value={p.id}>
                {p.displayName}
              </option>
            ))}
          </select>
        </label>
      )}
      <NavLink to="/pengaturan" className="btn btn--ghost btn--sm" aria-label={t('set.title')}>
        <Icon name="settings" size={18} />
      </NavLink>
    </header>
  )
}

function Fallback() {
  const t = useT()
  return (
    <p className="card__hint" role="status">
      {t('app.preparing')}
    </p>
  )
}

/** Scroll to top on route change — otherwise a long list keeps its offset. */
function ScrollReset() {
  const { pathname } = useLocation()
  if (typeof window !== 'undefined') window.scrollTo({ top: 0 })
  return <span key={pathname} hidden />
}

function Shell() {
  const t = useT()
  const { loading, profile, onboarded } = useSession()

  if (loading) {
    return (
      <div className="shell__main" role="status">
        <p>{t('app.loading')}</p>
      </div>
    )
  }

  if (!profile || !onboarded) return <Onboarding />

  return (
    <div className="shell">
      <a className="skip-link" href="#konten">
        {t('app.skipToContent')}
      </a>
      <Nav />
      <div className="grow">
        <TopBar />
        <main className="shell__main" id="konten">
          <ScrollReset />
          <Suspense fallback={<Fallback />}>
            <Routes>
              <Route path="/" element={<Today />} />
              <Route path="/aku" element={<Relationship soloMode />} />
              <Route path="/hubungan" element={<Relationship />} />
              <Route path="/kalender" element={<Calendar />} />
              <Route path="/momen" element={<Moments />} />
              <Route path="/kehidupan" element={<Household />} />
              <Route path="/keluarga" element={<Family />} />
              <Route path="/nikah" element={<Wedding />} />
              <Route path="/siklus" element={<Cycle />} />
              <Route path="/urusan" element={<Chores />} />
              <Route path="/uang" element={<Finance />} />
              <Route path="/keinginan" element={<Wishlist />} />
              <Route path="/kencan" element={<DateIdeas />} />
              <Route path="/linimasa" element={<Timeline />} />
              <Route path="/kesuburan" element={<Fertility />} />
              <Route path="/ngasuh" element={<Coparenting />} />
              <Route path="/sinkron" element={<Sync />} />
              <Route path="/kartu" element={<Cards />} />
              <Route path="/semua" element={<AllModules />} />
              <Route path="/privasi" element={<Privacy />} />
              <Route path="/bantuan" element={<Help />} />
              <Route path="/pengaturan" element={<Settings />} />
              {/* Design reference, not in the navigation. */}
              <Route path="/temu" element={<Companion />} />
              <Route path="/temu/perjalanan" element={<Journey />} />
              <Route path="/ikon" element={<IconGallery />} />
              <Route
                path="*"
                element={
                  <div className="card">
                    <h1>{t('app.notFound')}</h1>
                    <p className="card__hint">{t('app.notFoundHint')}</p>
                  </div>
                }
              />
            </Routes>
          </Suspense>
        </main>
      </div>
    </div>
  )
}

export default function App() {
  return (
    <I18nProvider>
      <ThemeProvider>
        <SessionProvider>
        {/* Hash routing keeps deep links working on GitHub Pages without a rewrite rule. */}
        <HashRouter>
          <Shell />
        </HashRouter>
        </SessionProvider>
      </ThemeProvider>
    </I18nProvider>
  )
}
