import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import { id as idMessages, type MessageKey as CoreMessageKey } from './id'
import { en as enMessages } from './en'
import { featureEn, featureId, type FeatureMessageKey } from './registry'

/** Core dictionary plus every registered feature bundle. */
export type MessageKey = CoreMessageKey | FeatureMessageKey

/**
 * Translation layer (Phase 14, blueprint 04 §11).
 *
 * Indonesian is primary and defines the key set; English is typed against it, so
 * a missing translation fails the build instead of silently falling through.
 * Business logic (`db/`, `cycleMath`, `pregnancyMath`, `unpair`) contains no
 * strings at all — only presentation calls `t()`.
 */

export type Locale = 'id' | 'en' | 'dwi'
export const LOCALES: readonly Locale[] = ['id', 'en', 'dwi']
export const LOCALE_LABEL: Record<Locale, string> = {
  id: 'Bahasa Indonesia',
  en: 'English',
  dwi: 'Dwibahasa (ID + EN)',
}

const DICT: Record<'id' | 'en', Record<string, string>> = {
  id: { ...idMessages, ...featureId },
  en: { ...enMessages, ...featureEn },
}

/**
 * Bilingual mode pairs the two languages on SHORT strings only — labels,
 * buttons, nav, headings. Body copy stays Indonesian.
 *
 * Doing it for everything was the obvious first idea and it is unusable: two
 * full paragraphs stacked in every card doubles the height of every screen and
 * pushes the actual content off the phone. Short strings are where a learner
 * or a mixed-language couple actually needs the second reading.
 */
const DWI_MAX = 34
function bilingual(id: string, en: string | undefined): string {
  if (!en || en === id) return id
  if (id.length > DWI_MAX) return id
  // A string with placeholders is shown once — interpolating the same value
  // into two copies reads like a stutter.
  if (/\{\w+\}/.test(id)) return id
  return `${id} · ${en}`
}
const STORAGE_KEY = 'temudua.locale'

export type Vars = Record<string, string | number>

/**
 * Narrows a locale to the two that actually have data behind them.
 *
 * Date, currency and number formatting take a real language; `dwi` is a display
 * mode, not a language, and formatting a date twice in two languages is noise.
 * Bilingual users get Indonesian formatting, which is what they are reading.
 */
export type DataLocale = 'id' | 'en'
export function baseLocale(locale: Locale): DataLocale {
  return locale === 'en' ? 'en' : 'id'
}

/** `{name}` → value. Unknown placeholders are left visible rather than blanked. */
function interpolate(template: string, vars?: Vars): string {
  if (!vars) return template
  return template.replace(/\{(\w+)\}/g, (whole, key: string) =>
    key in vars ? String(vars[key]) : whole,
  )
}

export function translate(locale: Locale, key: MessageKey, vars?: Vars): string {
  if (locale === 'dwi') {
    const both = bilingual(DICT.id[key] ?? key, DICT.en[key])
    return interpolate(both, vars)
  }
  // Indonesian is the fallback: a missing English string shows real copy, not a key.
  const raw = DICT[locale][key] ?? DICT.id[key]
  if (raw === undefined) {
    if (import.meta.env.DEV) console.warn(`[i18n] kunci hilang: ${key}`)
    return key
  }
  return interpolate(raw, vars)
}

export type TFunction = (key: MessageKey, vars?: Vars) => string

interface I18nValue {
  locale: Locale
  setLocale: (l: Locale) => void
  t: TFunction
}

const I18nContext = createContext<I18nValue | null>(null)

function detect(): Locale {
  const saved = localStorage.getItem(STORAGE_KEY)
  if (saved === 'id' || saved === 'en' || saved === 'dwi') return saved
  // ALWAYS Indonesian until the user says otherwise. This is an Indonesian
  // product for Indonesian couples; branching on navigator.language meant a
  // phone set to en-GB opened the whole app in English, which is how the first
  // real user saw it. English is a choice you make, not a default you inherit.
  return 'id'
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(detect)

  useEffect(() => {
    // `dwi` is not a language tag; the document is primarily Indonesian.
    document.documentElement.lang = locale === 'en' ? 'en' : 'id'
  }, [locale])

  const setLocale = useCallback((l: Locale) => {
    localStorage.setItem(STORAGE_KEY, l)
    setLocaleState(l)
  }, [])

  const value = useMemo<I18nValue>(
    () => ({
      locale,
      setLocale,
      t: (key, vars) => translate(locale, key, vars),
    }),
    [locale, setLocale],
  )

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n(): I18nValue {
  const ctx = useContext(I18nContext)
  if (!ctx) throw new Error('useI18n dipakai di luar I18nProvider')
  return ctx
}

/** Shorthand for the common case: a component that only needs `t`. */
export function useT(): TFunction {
  return useI18n().t
}


