import { useState } from 'react'
import { Icon, type IconName } from '@/design-system/Icon'
import { Field } from '@/components/ui'
import { useSession } from '@/app/session'
import { STAGE_DESC, STAGE_LABEL } from '@/app/nav'
import { db, newEnvelope } from '@/db/db'
import { STAGES, type PairingMode, type Stage } from '@/types/domain'
import './onboarding.css'
import { useT } from '@/i18n'

/**
 * Onboarding — blueprint 04 §4. One decision per screen, skippable, resumable.
 * The last step creates a real record so the user leaves onboarding with
 * something of their own already in the app (step 5: "first value").
 */

const FOCUS_OPTIONS = [
  { id: 'checkin', icon: 'checkin', stages: ['single', 'dating', 'married'] },
  { id: 'calendar', icon: 'calendar', stages: ['single', 'dating', 'married'] },
  { id: 'topics', icon: 'heart', stages: ['dating', 'married'] },
  { id: 'tasks', icon: 'tasks', stages: ['dating', 'married'] },
  { id: 'money', icon: 'money', stages: ['dating', 'married'] },
  { id: 'cycle', icon: 'cycle', stages: ['single', 'dating', 'married'] },
  { id: 'wedding', icon: 'ring', stages: ['dating'] },
  { id: 'family', icon: 'family', stages: ['married'] },
] as const satisfies readonly { id: string; icon: IconName; stages: readonly Stage[] }[]

const TOTAL = 6

export default function Onboarding() {
  const t = useT()
  const { createProfile, setPairingMode, finishOnboarding, refresh, profile } = useSession()
  const [step, setStep] = useState(profile ? 3 : 0)
  const [stage, setStage] = useState<Stage>(profile?.stage ?? 'dating')
  const [name, setName] = useState(profile?.displayName ?? '')
  const [pairing, setPairing] = useState<PairingMode>('solo')
  const [partnerName, setPartnerName] = useState('')
  const [focus, setFocus] = useState<string[]>([])
  const [shareDefault, setShareDefault] = useState<'private' | 'shared'>('private')
  const [firstThing, setFirstThing] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const next = () => setStep((s) => Math.min(s + 1, TOTAL - 1))
  const back = () => setStep((s) => Math.max(s - 1, 0))

  async function finish(skipFirstThing = false) {
    setBusy(true)
    setError(null)
    try {
      const me = profile ?? (await createProfile({ displayName: name, stage }))
      if (pairing === 'same_device' && partnerName.trim()) {
        const existing = await db.profiles.toArray()
        if (existing.length < 2) {
          const now = new Date().toISOString()
          await db.profiles.add({
            id: crypto.randomUUID(),
            displayName: partnerName.trim(),
            stage,
            locale: 'id',
            createdAt: now,
            stageHistory: [{ stage, changedAt: now }],
          })
          // Without this the partner exists in the database but not in session
          // state, so the profile switcher stays hidden until the next reload.
          await refresh()
        }
      }
      await setPairingMode(pairing)
      await db.settings.bulkPut([
        { key: 'onboarding.focus', value: focus },
        { key: 'onboarding.shareDefault', value: shareDefault },
      ])
      if (!skipFirstThing && firstThing.trim()) {
        await db.needs.add({
          ...newEnvelope(me.id, 'C3_relationship', {
            visibility: shareDefault === 'shared' ? 'shared' : 'private',
          }),
          kind: 'need',
          text: firstThing.trim(),
        } as never)
      }
      finishOnboarding()
    } catch (e) {
      setError(e instanceof Error ? e.message : t('onb.saveError'))
      setBusy(false)
    }
  }

  const focusForStage = FOCUS_OPTIONS.filter((f) => (f.stages as readonly Stage[]).includes(stage))

  return (
    <main className="onb" id="konten">
      <div className="onb__inner stack">
        <div className="onb__progress" aria-hidden="true">
          {Array.from({ length: TOTAL }, (_, i) => (
            <span key={i} data-done={i <= step} />
          ))}
        </div>
        <p className="visually-hidden" aria-live="polite">
          {t('onb.step', { n: step + 1, total: TOTAL })}
        </p>

        {step === 0 && (
          <section className="stack">
            <div className="onb__mascot">
              <Mascot />
            </div>
            <h1>{t('onb.welcome')}</h1>
            <p className="card__hint">{t('onb.welcomeBody')}
            </p>
            <button className="btn btn--block" onClick={next}>{t('onb.start')}
            </button>
          </section>
        )}

        {step === 1 && (
          <section className="stack">
            <h1>{t('onb.stageQ')}</h1>
            <p className="card__hint">{t('onb.stageHint')}</p>
            <div className="choices" role="radiogroup" aria-label={t('set.stage')}>
              {STAGES.map((s) => (
                <button
                  key={s}
                  type="button"
                  role="radio"
                  aria-checked={stage === s}
                  className="choice"
                  onClick={() => setStage(s)}
                >
                  <Icon name={s === 'single' ? 'self' : s === 'dating' ? 'heart' : 'home'} size={24} animate />
                  <span className="stack stack--tight">
                    <span className="choice__title">{t(STAGE_LABEL[s])}</span>
                    <span className="choice__desc">{t(STAGE_DESC[s])}</span>
                  </span>
                </button>
              ))}
            </div>
            <Nav onBack={back} onNext={next} />
          </section>
        )}

        {step === 2 && (
          <section className="stack">
            <h1>{t('onb.nameQ')}</h1>
            <Field label={t('onb.nameLabel')} hint={t('onb.nameHint')}>
              {(p) => (
                <input
                  {...p}
                  type="text"
                  value={name}
                  autoComplete="nickname"
                  placeholder={t('onb.namePlaceholder')}
                  onChange={(e) => setName(e.target.value)}
                />
              )}
            </Field>
            <Nav onBack={back} onNext={next} nextDisabled={!name.trim()} />
          </section>
        )}

        {step === 3 && (
          <section className="stack">
            <h1>{t('onb.pairQ')}</h1>
            <p className="card__hint">{t('onb.pairHint')}
            </p>
            <div className="choices" role="radiogroup" aria-label={t('onb.pairGroup')}>
              {(
                [
                  'solo',
                  'same_device',
                  'paired_export',
                ] as const
              ).map((o) => (
                <button
                  key={o}
                  type="button"
                  role="radio"
                  aria-checked={pairing === o}
                  className="choice"
                  onClick={() => setPairing(o)}
                >
                  <Icon name={o === 'solo' ? 'self' : 'shared'} size={24} animate />
                  <span className="stack stack--tight">
                    <span className="choice__title">{t(`onb.pair.${o}` as const)}</span>
                    <span className="choice__desc">{t(`onb.pair.${o}.desc` as const)}</span>
                  </span>
                </button>
              ))}
            </div>
            {pairing === 'same_device' && (
              <Field label={t('onb.partnerName')} hint={t('onb.partnerNameHint')}>
                {(p) => (
                  <input
                    {...p}
                    type="text"
                    value={partnerName}
                    onChange={(e) => setPartnerName(e.target.value)}
                  />
                )}
              </Field>
            )}
            <Nav onBack={back} onNext={next} />
          </section>
        )}

        {step === 4 && (
          <section className="stack">
            <h1>{t('onb.focusQ')}</h1>
            <p className="card__hint">{t('onb.focusHint')}</p>
            <div className="choices">
              {focusForStage.map((f) => {
                const on = focus.includes(f.id)
                const full = focus.length >= 3 && !on
                return (
                  <button
                    key={f.id}
                    type="button"
                    aria-pressed={on}
                    disabled={full}
                    className="choice"
                    onClick={() => setFocus((c) => (on ? c.filter((x) => x !== f.id) : [...c, f.id]))}
                  >
                    <Icon name={f.icon} size={24} animate />
                    <span className="stack stack--tight grow">
                      <span className="choice__title">{t(`focus.${f.id}` as const)}</span>
                      <span className="choice__desc">{t(`focus.${f.id}.desc` as const)}</span>
                    </span>
                    {on && <Icon name="check" size={20} />}
                  </button>
                )
              })}
            </div>
            <Nav onBack={back} onNext={next} />
          </section>
        )}

        {step === 5 && (
          <section className="stack">
            <h1>{t('onb.privacyQ')}</h1>
            <div className="choices" role="radiogroup" aria-label={t('onb.privacyGroup')}>
              <button
                type="button"
                role="radio"
                aria-checked={shareDefault === 'private'}
                className="choice"
                onClick={() => setShareDefault('private')}
              >
                <Icon name="private" size={24} animate />
                <span className="stack stack--tight">
                  <span className="choice__title">{t('onb.privacyPrivate')}</span>
                  <span className="choice__desc">{t('onb.privacyPrivateDesc')}
                  </span>
                </span>
              </button>
              <button
                type="button"
                role="radio"
                aria-checked={shareDefault === 'shared'}
                className="choice"
                onClick={() => setShareDefault('shared')}
              >
                <Icon name="shared" size={24} animate />
                <span className="stack stack--tight">
                  <span className="choice__title">{t('onb.privacyShared')}</span>
                  <span className="choice__desc">{t('onb.privacySharedDesc')}
                  </span>
                </span>
              </button>
            </div>
            <p className="disclaimer">{t('onb.healthAlwaysPrivate')}
            </p>

            <Field
              label={t('onb.firstThing')}
              hint={t('onb.firstThingHint')}
            >
              {(p) => (
                <input
                  {...p}
                  type="text"
                  value={firstThing}
                  placeholder={t('onb.firstThingPlaceholder')}
                  onChange={(e) => setFirstThing(e.target.value)}
                />
              )}
            </Field>

            {error && (
              <p className="banner banner--danger" role="alert">
                {error}
              </p>
            )}
            <div className="stack stack--tight">
              <button className="btn btn--block" disabled={busy} onClick={() => finish(false)}>
                {busy ? t('common.saving') : t('onb.enter')}
              </button>
              <button className="btn btn--ghost btn--block" disabled={busy} onClick={() => finish(true)}>{t('onb.skip')}
              </button>
            </div>
          </section>
        )}
      </div>
    </main>
  )
}

function Nav({
  onBack,
  onNext,
  nextDisabled,
}: {
  onBack: () => void
  onNext: () => void
  nextDisabled?: boolean
}) {
  const t = useT()
  return (
    <div className="row" style={{ gap: 'var(--space-2)' }}>
      <button className="btn btn--ghost" onClick={onBack}>
        <Icon name="chevron-left" size={18} />
        {t('common.back')}
      </button>
      <button className="btn grow" onClick={onNext} disabled={nextDisabled}>
        {t('common.next')}
      </button>
    </div>
  )
}

/** Two blobs — TemuDua's non-gendered mascots. Original artwork, SVG only. */
function Mascot() {
  const t = useT()
  return (
    <svg viewBox="0 0 200 120" role="img" aria-label={t('onb.mascotAlt')} width="200" height="120">
      <ellipse cx="100" cy="108" rx="70" ry="7" fill="var(--lavender-soft)" />
      <g className="onb-blob onb-blob--a">
        <path
          d="M78 96c-19 0-31-14-31-32 0-20 14-36 31-36s31 16 31 36c0 18-12 32-31 32Z"
          fill="var(--primary-soft)"
          stroke="var(--primary)"
          strokeWidth="2.4"
        />
        <circle cx="70" cy="58" r="3" fill="var(--ink)" />
        <circle cx="88" cy="58" r="3" fill="var(--ink)" />
        <path d="M72 70c4 4 10 4 14 0" stroke="var(--ink)" strokeWidth="2.4" fill="none" strokeLinecap="round" />
      </g>
      <g className="onb-blob onb-blob--b">
        <path
          d="M128 98c-16 0-27-12-27-27 0-17 12-31 27-31s27 14 27 31c0 15-11 27-27 27Z"
          fill="var(--blue-soft)"
          stroke="var(--blue)"
          strokeWidth="2.4"
        />
        <circle cx="121" cy="64" r="2.7" fill="var(--ink)" />
        <circle cx="136" cy="64" r="2.7" fill="var(--ink)" />
        <path d="M122 74c4 3.5 9 3.5 13 0" stroke="var(--ink)" strokeWidth="2.4" fill="none" strokeLinecap="round" />
      </g>
    </svg>
  )
}
