import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import type { MessageKey } from '@/i18n'

/**
 * Theme choice. Purely presentational — it writes one attribute on <html> and
 * `themes.css` does the rest, so no component ever branches on the theme.
 *
 * Stored in localStorage rather than the database on purpose: it is a per-device
 * preference, not shared couple data, and it must be readable before React
 * mounts (see the inline script in index.html) so the first paint is not the
 * wrong colour.
 */

export const THEMES = ['pastel', 'ceria', 'senja', 'embun', 'malam'] as const
export type Theme = (typeof THEMES)[number]

export const THEME_LABEL: Record<Theme, MessageKey> = {
  pastel: 'theme.pastel',
  ceria: 'theme.ceria',
  senja: 'theme.senja',
  embun: 'theme.embun',
  malam: 'theme.malam',
}

export const THEME_HINT: Record<Theme, MessageKey> = {
  pastel: 'theme.pastelHint',
  ceria: 'theme.ceriaHint',
  senja: 'theme.senjaHint',
  embun: 'theme.embunHint',
  malam: 'theme.malamHint',
}

/** Swatches for the picker, so the tiles show the theme instead of naming it. */
export const THEME_SWATCH: Record<Theme, string[]> = {
  pastel: ['#ff8fb3', '#5fd6c8', '#cdc4ff', '#ffdf6e'],
  ceria: ['#ff6fa5', '#2fd4c4', '#b39cff', '#ffd23f'],
  senja: ['#ff9a8b', '#ffca5f', '#c9b0e8', '#7fcfc0'],
  embun: ['#7ec8e8', '#6fdcc4', '#b7bff5', '#93ecc9'],
  malam: ['#ff8fb3', '#5fd6c8', '#1f2438', '#ffdf6e'],
}

const KEY = 'temudua.theme'

function read(): Theme | null {
  const v = localStorage.getItem(KEY)
  return (THEMES as readonly string[]).includes(v ?? '') ? (v as Theme) : null
}

interface ThemeValue {
  /** null = follow the operating system. */
  theme: Theme | null
  setTheme: (t: Theme | null) => void
}

const Ctx = createContext<ThemeValue | null>(null)

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<Theme | null>(read)

  useEffect(() => {
    const root = document.documentElement
    if (theme) root.setAttribute('data-theme', theme)
    else root.removeAttribute('data-theme')
  }, [theme])

  const setTheme = useCallback((t: Theme | null) => {
    if (t) localStorage.setItem(KEY, t)
    else localStorage.removeItem(KEY)
    setThemeState(t)
  }, [])

  const value = useMemo(() => ({ theme, setTheme }), [theme, setTheme])
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>
}

export function useTheme(): ThemeValue {
  const ctx = useContext(Ctx)
  if (!ctx) throw new Error('useTheme dipakai di luar ThemeProvider')
  return ctx
}
