import type { IconName } from '@/design-system/Icon'
import type { MessageKey } from '@/i18n'
import type { Stage } from '@/types/domain'

/**
 * Stage-based information architecture (blueprint 04 §2).
 * Max five items on mobile. A stage change reorders the shelf; it never removes
 * a route — everything stays reachable from "Kehidupan" and Settings.
 */

export interface NavItem {
  to: string
  /** Message key, resolved at render time so the shelf follows the locale. */
  label: MessageKey
  icon: IconName
}

/**
 * The five tabs.
 *
 * Rewritten because the old set buried the app. "Kehidupan" was a tasks screen
 * that also happened to be the only door to money, wedding, fertility,
 * co-parenting and everything else — so a user reasonably concluded those
 * features did not exist. Calendar, meanwhile, held a whole tab to itself while
 * fifteen modules shared one.
 *
 * The rule now: each tab is named for what is behind it, and the one called
 * "Semua" is honestly a directory rather than a screen pretending not to be.
 *
 *   Hari ini  — today: what is due, what to add
 *   Berdua    — the relationship: check-ins, needs, cards, Temu
 *   Rumah     — running the household: chores, money, calendar, groceries
 *   Semua     — every module, grouped and searchable
 *   Aku       — private to you: cycle, backup, settings
 */
// A sunrise, not a house: `home` was on this tab *and* on "Rumah", so the two
// most-used destinations in the bar were the same drawing.
const TODAY: NavItem = { to: '/', label: 'nav.today', icon: 'today' }
const US: NavItem = { to: '/hubungan', label: 'nav.us', icon: 'heart' }
const HOME: NavItem = { to: '/kehidupan', label: 'nav.home', icon: 'home' }
const ALL: NavItem = { to: '/semua', label: 'nav.all', icon: 'shared' }
// Labelled "Privasi", not "Aku": a solo user's shelf already carries "Buat
// aku" for their own reflections, and two tabs both reading as "me" is a
// coin-flip every time you reach for one. "Privasi" also says what is actually
// inside — backup, restore, and closing shared access.
const ME: NavItem = { to: '/privasi', label: 'nav.privacy', icon: 'private' }

export const NAV_BY_STAGE: Record<Stage, NavItem[]> = {
  // Solo users get "Aku" where a couple gets "Berdua"; everything else is the
  // same, because a household is a household whether one or two people run it.
  single: [TODAY, { to: '/aku', label: 'nav.self', icon: 'self' }, HOME, ALL, ME],
  dating: [TODAY, US, HOME, ALL, ME],
  married: [TODAY, US, HOME, ALL, ME],
}

export const STAGE_LABEL: Record<Stage, MessageKey> = {
  single: 'stage.single',
  dating: 'stage.dating',
  married: 'stage.married',
}

export const STAGE_DESC: Record<Stage, MessageKey> = {
  single: 'stage.single.desc',
  dating: 'stage.dating.desc',
  married: 'stage.married.desc',
}

/** Quick add actions, capped at six and filtered by stage (SHELL-04). */
export interface QuickAction {
  id: string
  label: MessageKey
  icon: IconName
  to: string
  stages: Stage[]
}

export const QUICK_ACTIONS: QuickAction[] = [
  { id: 'event', label: 'quick.event', icon: 'calendar', to: '/kalender?baru=1', stages: ['single', 'dating', 'married'] },
  { id: 'checkin', label: 'quick.checkin', icon: 'checkin', to: '/hubungan?baru=checkin', stages: ['dating', 'married'] },
  { id: 'self', label: 'quick.checkin', icon: 'checkin', to: '/aku?baru=checkin', stages: ['single'] },
  { id: 'need', label: 'quick.need', icon: 'heart', to: '/hubungan?baru=need', stages: ['single', 'dating', 'married'] },
  { id: 'task', label: 'quick.task', icon: 'tasks', to: '/kehidupan?baru=task', stages: ['dating', 'married'] },
  { id: 'bill', label: 'quick.bill', icon: 'money', to: '/kehidupan?baru=bill', stages: ['dating', 'married'] },
  { id: 'memory', label: 'quick.memory', icon: 'memories', to: '/momen?baru=1', stages: ['dating', 'married'] },
  { id: 'wedding', label: 'quick.wedding', icon: 'ring', to: '/nikah', stages: ['dating'] },
  { id: 'cycle', label: 'quick.cycle', icon: 'cycle', to: '/siklus?baru=1', stages: ['single', 'dating', 'married'] },
]

export function quickActionsFor(stage: Stage): QuickAction[] {
  return QUICK_ACTIONS.filter((a) => a.stages.includes(stage)).slice(0, 6)
}

/**
 * Modules that live under the "Kehidupan" hub rather than the shelf.
 *
 * The bottom nav is full at five items for all three stages, and five is a hard
 * cap on mobile, not a target — so every module added after the first wave is
 * reachable from here instead. That is the rule the file header already states:
 * a stage never removes a route, it only reorders the shelf.
 *
 * Labels reuse each feature's own `<feature>.title` key, so this list needs no
 * dictionary entries of its own and cannot drift from the screen it opens.
 */
export interface ModuleLink extends NavItem {
  /** Stages this module is *suggested* for. It never hides anything — see below. */
  suggested: Stage[]
  /** One line explaining what the module is for, shown in the hub. */
  desc: MessageKey
}

/**
 * Every module in the app, in one list.
 *
 * `suggested` orders the hub; it does NOT gate access. A module used to be
 * filtered out entirely when it did not match your stage, which meant a couple
 * who picked "pacaran" could not find the wedding planner, the money spaces or
 * the fertility screens at all — the app looked like it had five features when
 * it has fifteen. Wedding was worse: it was missing from this list altogether
 * and only reachable from a quick-action chip.
 *
 * Nothing here is destructive to see. Screens that hold sensitive data still
 * open in their own quiet default state, so showing the door costs nothing.
 */
export const MODULE_LINKS: ModuleLink[] = [
  { to: '/kartu', label: 'cards.title', desc: 'mod.cardsDesc', icon: 'cards', suggested: ['single', 'dating', 'married'] },
  { to: '/urusan', label: 'chores.title', desc: 'mod.choresDesc', icon: 'mentalload', suggested: ['dating', 'married'] },
  { to: '/uang', label: 'finance2.title', desc: 'mod.moneyDesc', icon: 'money', suggested: ['single', 'dating', 'married'] },
  { to: '/nikah', label: 'wed.title', desc: 'mod.weddingDesc', icon: 'ring', suggested: ['dating', 'married'] },
  { to: '/keinginan', label: 'wishlist.title', desc: 'mod.wishlistDesc', icon: 'groceries', suggested: ['single', 'dating', 'married'] },
  { to: '/kencan', label: 'dates.title', desc: 'mod.datesDesc', icon: 'date', suggested: ['dating', 'married'] },
  { to: '/linimasa', label: 'timeline.title', desc: 'mod.timelineDesc', icon: 'memories', suggested: ['dating', 'married'] },
  // Neutral label: the screen defaults to the quiet 'tidak' mode, so the hub
  // entry must not read "Program hamil & kehamilan" to someone who never asked.
  { to: '/kesuburan', label: 'fertility.title.quiet', desc: 'mod.fertilityDesc', icon: 'pregnancy', suggested: ['dating', 'married'] },
  { to: '/ngasuh', label: 'coparenting.title', desc: 'mod.coparentingDesc', icon: 'baby', suggested: ['single', 'dating', 'married'] },
  { to: '/kalender', label: 'nav.calendar', desc: 'mod.calendarDesc', icon: 'calendar', suggested: ['single', 'dating', 'married'] },
  { to: '/siklus', label: 'cyc.title', desc: 'mod.cycleDesc', icon: 'cycle', suggested: ['single', 'dating', 'married'] },
  { to: '/momen', label: 'mem.title', desc: 'mod.momentsDesc', icon: 'memories', suggested: ['dating', 'married'] },
  { to: '/temu', label: 'temu.title', desc: 'mod.temuDesc', icon: 'temu', suggested: ['dating', 'married'] },
  { to: '/sinkron', label: 'sync.title', desc: 'mod.syncDesc', icon: 'shared', suggested: ['single', 'dating', 'married'] },
  { to: '/privasi', label: 'priv.title', desc: 'mod.privacyDesc', icon: 'shield', suggested: ['single', 'dating', 'married'] },
]

/**
 * The four the app leads with, in the order they appear on Hari ini.
 *
 * Kept here rather than in a component so the tiles on the front page and the
 * directory cannot drift apart and start disagreeing about what is "utama".
 */
export const MAIN_MODULES = ['/kalender', '/uang', '/temu', '/kartu'] as const

export function mainModules(): ModuleLink[] {
  return MAIN_MODULES.map((to) => MODULE_LINKS.find((m) => m.to === to)).filter(
    (m): m is ModuleLink => !!m,
  )
}

/** Suggested for this stage — shown first in the hub. */
export function moduleLinksFor(stage: Stage): ModuleLink[] {
  return MODULE_LINKS.filter(
    (m) => m.suggested.includes(stage) && !MAIN_MODULES.includes(m.to as (typeof MAIN_MODULES)[number]),
  )
}

/** Everything else. Still reachable, just listed after the suggestions. */
export function otherModulesFor(stage: Stage): ModuleLink[] {
  return MODULE_LINKS.filter(
    (m) => !m.suggested.includes(stage) && !MAIN_MODULES.includes(m.to as (typeof MAIN_MODULES)[number]),
  )
}

